-- TORVO V2 secure business action RPCs. Actor identity always comes from auth.uid().
create or replace function approve_dealer(p_dealer uuid,p_dealer_code text,p_rate_group text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype; s text; begin select * into a from app_users where auth_user_id=auth.uid() and active=true; if not found or a.role not in ('owner','admin') then raise exception 'Not authorized'; end if; if p_rate_group not in ('A','B','C') or nullif(trim(p_dealer_code),'') is null then raise exception 'Dealer code and valid rate group required'; end if; select status into s from dealers where id=p_dealer for update; if not found then raise exception 'Dealer not found'; end if; if s='approved' then raise exception 'Dealer already approved'; end if; update dealers set dealer_code=upper(trim(p_dealer_code)),rate_group=p_rate_group,status='approved',approved_by=a.id,approved_at=now() where id=p_dealer; insert into dealer_request_history(dealer_id,action,reason,actor_id) values(p_dealer,'approved','Dealer approved with rate group '||p_rate_group,a.id); insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'DEALER_APPROVED','dealer',p_dealer::text,jsonb_build_object('dealer_code',upper(trim(p_dealer_code)),'rate_group',p_rate_group)); end;$$;
revoke all on function approve_dealer(uuid,text,text) from public,anon; grant execute on function approve_dealer(uuid,text,text) to authenticated;
create or replace function set_dealer_request_status(p_dealer uuid,p_status text,p_reason text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype; begin select * into a from app_users where auth_user_id=auth.uid() and active=true; if not found or a.role not in ('owner','admin') then raise exception 'Not authorized'; end if; if p_status not in ('hold','rejected','inactive','suspended') or nullif(trim(p_reason),'') is null then raise exception 'Valid status and reason required'; end if; perform 1 from dealers where id=p_dealer for update; if not found then raise exception 'Dealer not found'; end if; update dealers set status=p_status where id=p_dealer; insert into dealer_request_history(dealer_id,action,reason,actor_id) values(p_dealer,p_status,trim(p_reason),a.id); insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'DEALER_STATUS_CHANGED','dealer',p_dealer::text,jsonb_build_object('status',p_status,'reason',trim(p_reason))); end;$$;
revoke all on function set_dealer_request_status(uuid,text,text) from public,anon; grant execute on function set_dealer_request_status(uuid,text,text) to authenticated;
create or replace function record_payment(p_estimate uuid,p_status text,p_amount numeric) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype; pid uuid; f numeric; paid numeric; begin select * into a from app_users where auth_user_id=auth.uid() and active=true; if not found or a.role not in ('owner','admin','accountant') then raise exception 'Not authorized'; end if; if p_status not in ('cash','pending','received') or p_amount is null or p_amount<=0 then raise exception 'Payment amount must be greater than zero'; end if; select final_payable into f from sales_documents where id=p_estimate and doc_type='estimate' for update; if not found then raise exception 'Estimate not found'; end if; if f is null or f<=0 then raise exception 'Estimate final payable is invalid'; end if; select coalesce(sum(amount),0) into paid from payments where estimate_id=p_estimate and status in('cash','received'); if p_status in('cash','received') and paid+p_amount>f then raise exception 'Payment exceeds outstanding amount'; end if; insert into payments(estimate_id,status,amount,received_at,recorded_by) values(p_estimate,p_status,p_amount,case when p_status in ('cash','received') then now() else null end,a.id) returning id into pid; insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'PAYMENT_RECORDED','estimate',p_estimate::text,jsonb_build_object('payment_id',pid,'status',p_status,'amount',p_amount,'final_payable',f,'received_before',paid)); return pid; end;$$;
revoke all on function record_payment(uuid,text,numeric) from public,anon; grant execute on function record_payment(uuid,text,numeric) to authenticated;
create or replace function advance_dispatch(p_estimate uuid,p_status text,p_tracking_code text default null) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype; cur text; nxt text; begin select * into a from app_users where auth_user_id=auth.uid() and active=true; if not found or a.role not in ('owner','admin','store_keeper') then raise exception 'Not authorized'; end if; if p_status='delivered' then raise exception 'Use deliver_estimate for delivery'; end if; select status into cur from dispatches where estimate_id=p_estimate for update; if not found then raise exception 'Dispatch not found'; end if; nxt:=case cur when 'pick_list' then 'picked' when 'picked' then 'packed' when 'packed' then 'ready_for_dispatch' else null end; if p_status<>nxt then raise exception 'Invalid dispatch transition'; end if; update dispatches set status=p_status,tracking_code=coalesce(nullif(trim(p_tracking_code),''),tracking_code),updated_by=a.id where estimate_id=p_estimate; insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'DISPATCH_STATUS_CHANGED','estimate',p_estimate::text,jsonb_build_object('from',cur,'to',p_status)); end;$$;
revoke all on function advance_dispatch(uuid,text,text) from public,anon; grant execute on function advance_dispatch(uuid,text,text) to authenticated;
